/ ── 力参数：只设一次，运行时函数通过 ref 读最新配置 ──
  useEffect(() => {
    const fg = fgRef.current;
    if (!fg) return;

    fg.d3Force("r", forceRadial((node: any) => {
      const { radialR, maxDegree, degreeMap } = forceCfg.current;
      const deg = degreeMap.get(node.id) || 0;
      const t = maxDegree > 0 ? deg / maxDegree : 0; // 0..1
      const rMin = radialR * 0.25;
      return radialR - t * (radialR - rMin);
    }).strength(0.35));

    fg.d3Force("charge")?.strength(0);
    fg.d3Force("link")?.distance(50)?.strength(0.5);
    fg.d3Force("center")?.strength(0.4);
    fg.d3Force("collision", forceCollide(10));
  }, []);

